{
	double num = e.Delta;
	double num2 = fxr(e.X);
	double num3 = fyr(e.Y);
	if (num > 0.0)
	{
		_scaleX *= 1.1;
		_scaleY *= 1.1;
	}
	else
	{
		_scaleX /= 1.1;
		_scaleY /= 1.1;
	}
	double num4 = fxr(e.X);
